with exp(k,h) as (values ('apcalcab-mcq-orly-c1-v1','ad49e2327ca44d00ab2b5a48c8609aab'),('apcalcab-mcq-orly-c1-v2','edb79adf492c42fbbc93f19aa72b1348'),('apcalcab-mcq-orly-c1-v3','f70b145de47757670280fc3b533c56f5'),('apcalcab-mcq-orly-c2-v1','c1e1801b480404c661f1f8d9cb77c25c'),('apcalcab-mcq-orly-c2-v2','5e81f298df70ee009ea93fd6a797c1cf'),('apcalcab-mcq-orly-c2-v3','1282815d9f92c3a5f892a8122379ac0d')), got as (select ci.content_key k, md5(civ.stem||'|'||string_agg(c.choice_key||':'||c.choice_text||':'||c.is_correct::text||':'||c.rationale,'|' order by c.choice_key)) h from app.content_items ci join app.content_item_versions civ on civ.content_item_id=ci.id and civ.status='published' join app.mcq_choices c on c.content_item_version_id=civ.id where ci.exam_pack_version_id='826c8cf1-bc1b-4f2a-bd33-61a758e1487d' and ci.content_key in (select k from exp) group by ci.content_key, civ.stem) select (select count(*) from exp) expected, (select count(*) from got) loaded, (select count(*) from exp join got using(k) where exp.h=got.h) matching;